INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('30253e1f-925b-4f15-91f6-2e17bd33dc3b', 'd76b66b3-91e8-44ba-8353-f22c5acbfc58', '9a062817-19df-4d75-94ee-44c7079777a9', 'grype', 'CVE-2026-27140', 'HIGH', 'stdlib', 'go1.26.1', '1.25.9', '', 'SWIG file names containing ''cgo'' and well-crafted payloads could lead to code smuggling and arbitrary code execution at build time due to trust layer bypass.', '/app/homelab', '2026-04-17 15:46:33.764156+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('9b2bc688-3a92-406e-99f4-b66ec64ea3b9', 'd76b66b3-91e8-44ba-8353-f22c5acbfc58', '9a062817-19df-4d75-94ee-44c7079777a9', 'grype', 'CVE-2026-32280', 'HIGH', 'stdlib', 'go1.26.1', '1.25.9', '', 'During chain building, the amount of work that is done is not correctly limited when a large number of intermediate certificates are passed in VerifyOptions.Intermediates, which can lead to a denial of service. This affects both direct users of crypto/x509 and users of crypto/tls.', '/app/homelab', '2026-04-17 15:46:33.764156+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('75d945ad-eb37-4ee2-9d90-442768d7abb5', 'd76b66b3-91e8-44ba-8353-f22c5acbfc58', '9a062817-19df-4d75-94ee-44c7079777a9', 'grype', 'CVE-2026-32281', 'HIGH', 'stdlib', 'go1.26.1', '1.25.9', '', 'Validating certificate chains which use policies is unexpectedly inefficient when certificates in the chain contain a very large number of policy mappings, possibly causing denial of service. This only affects validation of otherwise trusted certificate chains, issued by a root CA in the VerifyOptions.Roots CertPool, or in the system certificate pool.', '/app/homelab', '2026-04-17 15:46:33.764156+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('15eaada6-c3c5-4cc8-9f7e-f34e1842272e', 'd76b66b3-91e8-44ba-8353-f22c5acbfc58', '9a062817-19df-4d75-94ee-44c7079777a9', 'grype', 'CVE-2026-32283', 'HIGH', 'stdlib', 'go1.26.1', '1.25.9', '', 'If one side of the TLS connection sends multiple key update messages post-handshake in a single record, the connection can deadlock, causing uncontrolled consumption of resources. This can lead to a denial of service. This only affects TLS 1.3.', '/app/homelab', '2026-04-17 15:46:33.764156+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('18d2cab2-2016-41c3-9c84-6a7549eac4bc', 'd76b66b3-91e8-44ba-8353-f22c5acbfc58', '9a062817-19df-4d75-94ee-44c7079777a9', 'grype', 'CVE-2026-33810', 'HIGH', 'stdlib', 'go1.26.1', '1.26.2', '', 'When verifying a certificate chain containing excluded DNS constraints, these constraints are not correctly applied to wildcard DNS SANs which use a different case than the constraint. This only affects validation of otherwise trusted certificate chains, issued by a root CA in the VerifyOptions.Roots CertPool, or in the system certificate pool.', '/app/homelab', '2026-04-17 15:46:33.764156+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('967c43df-7d16-4044-a6a4-b63c11d05f3b', 'd76b66b3-91e8-44ba-8353-f22c5acbfc58', '9a062817-19df-4d75-94ee-44c7079777a9', 'grype', 'CVE-2026-32282', 'MEDIUM', 'stdlib', 'go1.26.1', '1.25.9', '', 'On Linux, if the target of Root.Chmod is replaced with a symlink while the chmod operation is in progress, Chmod can operate on the target of the symlink, even when the target lies outside the root. The Linux fchmodat syscall silently ignores the AT_SYMLINK_NOFOLLOW flag, which Root.Chmod uses to avoid symlink traversal. Root.Chmod checks its target before acting and returns an error if the target is a symlink lying outside the root, so the impact is limited to cases where the target is replaced with a symlink between the check and operation.', '/app/homelab', '2026-04-17 15:46:33.764156+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('ec0c3b9f-ba04-4b8d-ad01-8f721d6d62ff', 'd76b66b3-91e8-44ba-8353-f22c5acbfc58', '9a062817-19df-4d75-94ee-44c7079777a9', 'grype', 'CVE-2026-32288', 'MEDIUM', 'stdlib', 'go1.26.1', '1.25.9', '', 'tar.Reader can allocate an unbounded amount of memory when reading a maliciously-crafted archive containing a large number of sparse regions encoded in the "old GNU sparse map" format.', '/app/homelab', '2026-04-17 15:46:33.764156+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('87b0b2c7-5733-4b17-9abe-65d649a54bdb', 'd76b66b3-91e8-44ba-8353-f22c5acbfc58', '9a062817-19df-4d75-94ee-44c7079777a9', 'grype', 'CVE-2026-32289', 'MEDIUM', 'stdlib', 'go1.26.1', '1.25.9', '', 'Context was not properly tracked across template branches for JS template literals, leading to possibly incorrect escaping of content when branches were used. Additionally template actions within JS template literals did not properly track the brace depth, leading to incorrect escaping being applied. These issues could cause actions within JS template literals to be incorrectly or improperly escaped, leading to XSS vulnerabilities.', '/app/homelab', '2026-04-17 15:46:33.764156+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('7653a9ad-8be4-41a7-af7c-078a0c6b1aa1', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-22871', 'CRITICAL', 'stdlib', 'go1.23.4', '1.23.8', '', 'The net/http package improperly accepts a bare LF as a line terminator in chunked data chunk-size lines. This can permit request smuggling if a net/http server is used in conjunction with a server that incorrectly accepts a bare LF as part of a chunk-ext.', '/usr/local/bin/gomplate', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('4b1482de-9191-4bd2-b0d5-4d8b5c1b36fd', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-68121', 'CRITICAL', 'stdlib', 'go1.24.3', '1.24.13', '', 'During session resumption in crypto/tls, if the underlying Config has its ClientCAs or RootCAs fields mutated between the initial handshake and the resumed handshake, the resumed handshake may succeed when it should have failed. This may happen when a user calls Config.Clone and mutates the returned Config, or uses Config.GetConfigForClient. This can cause a client to resume a session with a server that it would not have resumed with during the initial handshake, or cause a server to resume a session with a client that it would not have resumed with during the initial handshake.', '/usr/local/bin/dex', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('6888b61a-8cd1-4f9b-be6a-5403f4803d1a', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-68121', 'CRITICAL', 'stdlib', 'go1.23.4', '1.24.13', '', 'During session resumption in crypto/tls, if the underlying Config has its ClientCAs or RootCAs fields mutated between the initial handshake and the resumed handshake, the resumed handshake may succeed when it should have failed. This may happen when a user calls Config.Clone and mutates the returned Config, or uses Config.GetConfigForClient. This can cause a client to resume a session with a server that it would not have resumed with during the initial handshake, or cause a server to resume a session with a client that it would not have resumed with during the initial handshake.', '/usr/local/bin/gomplate', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('6c9ebf06-4094-4928-b3bb-8aefb5f8bc4d', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-68121', 'CRITICAL', 'stdlib', 'go1.24.3', '1.24.13', '', 'During session resumption in crypto/tls, if the underlying Config has its ClientCAs or RootCAs fields mutated between the initial handshake and the resumed handshake, the resumed handshake may succeed when it should have failed. This may happen when a user calls Config.Clone and mutates the returned Config, or uses Config.GetConfigForClient. This can cause a client to resume a session with a server that it would not have resumed with during the initial handshake, or cause a server to resume a session with a client that it would not have resumed with during the initial handshake.', '/usr/local/bin/docker-entrypoint', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('2341ab67-f497-4a1f-90c4-b3b3c965f92a', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'GHSA-p77j-4mvh-x3m3', 'CRITICAL', 'google.golang.org/grpc', 'v1.72.1', '1.79.3', '', 'gRPC-Go has an authorization bypass via missing leading slash in :path', '/usr/local/bin/dex', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('48576a67-eadd-456a-b111-05cb8165b04d', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'GHSA-p77j-4mvh-x3m3', 'CRITICAL', 'google.golang.org/grpc', 'v1.68.1', '1.79.3', '', 'gRPC-Go has an authorization bypass via missing leading slash in :path', '/usr/local/bin/gomplate', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('17e3fe7f-d3dc-428d-a552-c01cbf905e91', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-15467', 'HIGH', 'libcrypto3', '3.3.3-r0', '3.3.6-r0', '', '', '/lib/apk/db/installed', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('55bcc352-0818-46f1-aded-2896464af3bf', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-15467', 'HIGH', 'libssl3', '3.3.3-r0', '3.3.6-r0', '', '', '/lib/apk/db/installed', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('95a2d07d-35b3-4d54-b635-3b0b380edd8b', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-22874', 'HIGH', 'stdlib', 'go1.24.3', '1.24.4', '', 'Calling Verify with a VerifyOptions.KeyUsages that contains ExtKeyUsageAny unintentionally disabledpolicy validation. This only affected certificate chains which contain policy graphs, which are rather uncommon.', '/usr/local/bin/dex', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('ab4044de-3855-4eff-8c97-8fb7bc519842', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-22874', 'HIGH', 'stdlib', 'go1.24.3', '1.24.4', '', 'Calling Verify with a VerifyOptions.KeyUsages that contains ExtKeyUsageAny unintentionally disabledpolicy validation. This only affected certificate chains which contain policy graphs, which are rather uncommon.', '/usr/local/bin/docker-entrypoint', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('44acbada-064a-4c22-b99e-24a027748481', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-4674', 'HIGH', 'stdlib', 'go1.23.4', '1.23.11', '', 'The go command may execute unexpected commands when operating in untrusted VCS repositories. This occurs when possibly dangerous VCS configuration is present in repositories. This can happen when a repository was fetched via one VCS (e.g. Git), but contains metadata for another VCS (e.g. Mercurial). Modules which are retrieved using the go command line, i.e. via "go get", are not affected.', '/usr/local/bin/gomplate', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('cdee6622-1fa4-4a1c-8a52-ea7afa1ceb49', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-4674', 'HIGH', 'stdlib', 'go1.24.3', '1.23.11', '', 'The go command may execute unexpected commands when operating in untrusted VCS repositories. This occurs when possibly dangerous VCS configuration is present in repositories. This can happen when a repository was fetched via one VCS (e.g. Git), but contains metadata for another VCS (e.g. Mercurial). Modules which are retrieved using the go command line, i.e. via "go get", are not affected.', '/usr/local/bin/dex', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('4cdbff82-4156-4854-9427-5c8b5f7b56ce', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-4674', 'HIGH', 'stdlib', 'go1.24.3', '1.23.11', '', 'The go command may execute unexpected commands when operating in untrusted VCS repositories. This occurs when possibly dangerous VCS configuration is present in repositories. This can happen when a repository was fetched via one VCS (e.g. Git), but contains metadata for another VCS (e.g. Mercurial). Modules which are retrieved using the go command line, i.e. via "go get", are not affected.', '/usr/local/bin/docker-entrypoint', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('165a13a0-de22-4f55-a9cf-bfdf7e2d8c97', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-47907', 'HIGH', 'stdlib', 'go1.24.3', '1.23.12', '', 'Cancelling a query (e.g. by cancelling the context passed to one of the query methods) during a call to the Scan method of the returned Rows can result in unexpected results if other queries are being made in parallel. This can result in a race condition that may overwrite the expected results with those of another query, causing the call to Scan to return either unexpected results from the other query or an error.', '/usr/local/bin/dex', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('ce46cfc7-d5bd-429f-b098-7301d57fefba', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-47907', 'HIGH', 'stdlib', 'go1.23.4', '1.23.12', '', 'Cancelling a query (e.g. by cancelling the context passed to one of the query methods) during a call to the Scan method of the returned Rows can result in unexpected results if other queries are being made in parallel. This can result in a race condition that may overwrite the expected results with those of another query, causing the call to Scan to return either unexpected results from the other query or an error.', '/usr/local/bin/gomplate', '2026-04-17 15:47:31.780237+00');
