INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('65828aba-0be9-4ff4-8c15-bbfb1f73e09c', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61726', 'HIGH', 'stdlib', 'go1.23.4', '1.24.12', '', 'The net/url package does not set a limit on the number of query parameters in a query. While the maximum size of query parameters in URLs is generally limited by the maximum request header size, the net/http.Request.ParseForm method can parse large URL-encoded forms. Parsing a large form containing many unique query parameters can cause excessive memory consumption.', '/usr/local/bin/gomplate', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('8e015c9f-d7d5-4a99-ba73-2c9e712453bf', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61726', 'HIGH', 'stdlib', 'go1.24.3', '1.24.12', '', 'The net/url package does not set a limit on the number of query parameters in a query. While the maximum size of query parameters in URLs is generally limited by the maximum request header size, the net/http.Request.ParseForm method can parse large URL-encoded forms. Parsing a large form containing many unique query parameters can cause excessive memory consumption.', '/usr/local/bin/dex', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('7dd5076a-1386-4e39-bcba-8bc79bf534ff', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61726', 'HIGH', 'stdlib', 'go1.24.3', '1.24.12', '', 'The net/url package does not set a limit on the number of query parameters in a query. While the maximum size of query parameters in URLs is generally limited by the maximum request header size, the net/http.Request.ParseForm method can parse large URL-encoded forms. Parsing a large form containing many unique query parameters can cause excessive memory consumption.', '/usr/local/bin/docker-entrypoint', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('3782a711-78c7-403d-b7c4-2b5dfd7b1f2a', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61729', 'HIGH', 'stdlib', 'go1.23.4', '1.24.11', '', 'Within HostnameError.Error(), when constructing an error string, there is no limit to the number of hosts that will be printed out. Furthermore, the error string is constructed by repeated string concatenation, leading to quadratic runtime. Therefore, a certificate provided by a malicious actor can result in excessive resource consumption.', '/usr/local/bin/gomplate', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('e748dc1f-62d5-4251-a627-af79c0457be3', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61729', 'HIGH', 'stdlib', 'go1.24.3', '1.24.11', '', 'Within HostnameError.Error(), when constructing an error string, there is no limit to the number of hosts that will be printed out. Furthermore, the error string is constructed by repeated string concatenation, leading to quadratic runtime. Therefore, a certificate provided by a malicious actor can result in excessive resource consumption.', '/usr/local/bin/dex', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('4a5e0012-0193-4c14-8c19-8b28834b9a6d', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61729', 'HIGH', 'stdlib', 'go1.24.3', '1.24.11', '', 'Within HostnameError.Error(), when constructing an error string, there is no limit to the number of hosts that will be printed out. Furthermore, the error string is constructed by repeated string concatenation, leading to quadratic runtime. Therefore, a certificate provided by a malicious actor can result in excessive resource consumption.', '/usr/local/bin/docker-entrypoint', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('a7c14805-8be7-4a55-9299-d2fa4176a33f', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61731', 'HIGH', 'stdlib', 'go1.24.3', '1.24.12', '', 'Building a malicious file with cmd/go can cause can cause a write to an attacker-controlled file with partial control of the file content. The "#cgo pkg-config:" directive in a Go source file provides command-line arguments to provide to the Go pkg-config command. An attacker can provide a "--log-file" argument to this directive, causing pkg-config to write to an attacker-controlled location.', '/usr/local/bin/docker-entrypoint', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('44f9bd62-b75c-447d-8fd8-b7a8ca15281e', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61731', 'HIGH', 'stdlib', 'go1.24.3', '1.24.12', '', 'Building a malicious file with cmd/go can cause can cause a write to an attacker-controlled file with partial control of the file content. The "#cgo pkg-config:" directive in a Go source file provides command-line arguments to provide to the Go pkg-config command. An attacker can provide a "--log-file" argument to this directive, causing pkg-config to write to an attacker-controlled location.', '/usr/local/bin/dex', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('291e2fab-c59c-4787-aba4-31a538055da0', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61731', 'HIGH', 'stdlib', 'go1.23.4', '1.24.12', '', 'Building a malicious file with cmd/go can cause can cause a write to an attacker-controlled file with partial control of the file content. The "#cgo pkg-config:" directive in a Go source file provides command-line arguments to provide to the Go pkg-config command. An attacker can provide a "--log-file" argument to this directive, causing pkg-config to write to an attacker-controlled location.', '/usr/local/bin/gomplate', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('0103abf1-ba31-47b8-81b8-7e8a84bbd634', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61732', 'HIGH', 'stdlib', 'go1.24.3', '1.24.13', '', 'A discrepancy between how Go and C/C++ comments were parsed allowed for code smuggling into the resulting cgo binary.', '/usr/local/bin/docker-entrypoint', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('584ed79f-7b33-4f45-86d5-7f58fb0db42f', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61732', 'HIGH', 'stdlib', 'go1.24.3', '1.24.13', '', 'A discrepancy between how Go and C/C++ comments were parsed allowed for code smuggling into the resulting cgo binary.', '/usr/local/bin/dex', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('698f71c6-d9c3-427b-8aa1-639e1a01e416', 'ef58aad0-a78d-46f9-b003-b7aadf1560f7', 'a7fcfa9c-24cf-4bc3-8e73-d524fe1b4668', 'grype', 'CVE-2025-61732', 'HIGH', 'stdlib', 'go1.23.4', '1.24.13', '', 'A discrepancy between how Go and C/C++ comments were parsed allowed for code smuggling into the resulting cgo binary.', '/usr/local/bin/gomplate', '2026-04-17 15:47:31.780237+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('13d90035-4760-4bf2-905b-d7470a376ba9', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-68121', 'CRITICAL', 'stdlib', 'go1.24.3', '1.24.13', '', 'During session resumption in crypto/tls, if the underlying Config has its ClientCAs or RootCAs fields mutated between the initial handshake and the resumed handshake, the resumed handshake may succeed when it should have failed. This may happen when a user calls Config.Clone and mutates the returned Config, or uses Config.GetConfigForClient. This can cause a client to resume a session with a server that it would not have resumed with during the initial handshake, or cause a server to resume a session with a client that it would not have resumed with during the initial handshake.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('1a092696-018f-482d-b1e1-eaf9e37e3467', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-22874', 'HIGH', 'stdlib', 'go1.24.3', '1.24.4', '', 'Calling Verify with a VerifyOptions.KeyUsages that contains ExtKeyUsageAny unintentionally disabledpolicy validation. This only affected certificate chains which contain policy graphs, which are rather uncommon.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('cfb56f03-9639-40c2-94f4-64d59a9f3079', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-4674', 'HIGH', 'stdlib', 'go1.24.3', '1.23.11', '', 'The go command may execute unexpected commands when operating in untrusted VCS repositories. This occurs when possibly dangerous VCS configuration is present in repositories. This can happen when a repository was fetched via one VCS (e.g. Git), but contains metadata for another VCS (e.g. Mercurial). Modules which are retrieved using the go command line, i.e. via "go get", are not affected.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('72d15b11-5966-4125-826c-095a8c5774ee', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-47907', 'HIGH', 'stdlib', 'go1.24.3', '1.23.12', '', 'Cancelling a query (e.g. by cancelling the context passed to one of the query methods) during a call to the Scan method of the returned Rows can result in unexpected results if other queries are being made in parallel. This can result in a race condition that may overwrite the expected results with those of another query, causing the call to Scan to return either unexpected results from the other query or an error.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('da17fcae-302c-460a-a049-c812ce06ea8d', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-58187', 'HIGH', 'stdlib', 'go1.24.3', '1.24.9', '', 'Due to the design of the name constraint checking algorithm, the processing time of some inputs scale non-linearly with respect to the size of the certificate. This affects programs which validate arbitrary certificate chains.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('0334c8bd-c759-424d-a9a8-d2d125b141f4', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-58188', 'HIGH', 'stdlib', 'go1.24.3', '1.24.8', '', 'Validating certificate chains which contain DSA public keys can cause programs to panic, due to a interface cast that assumes they implement the Equal method. This affects programs which validate arbitrary certificate chains.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('8038b664-b116-4dc1-afda-37581e1dce59', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-61723', 'HIGH', 'stdlib', 'go1.24.3', '1.24.8', '', 'The processing time for parsing some invalid inputs scales non-linearly with respect to the size of the input. This affects programs which parse untrusted PEM inputs.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('7177f73c-a31b-431b-a15f-c740f3424a53', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-61725', 'HIGH', 'stdlib', 'go1.24.3', '1.24.8', '', 'The ParseAddress function constructs domain-literal address components through repeated string concatenation. When parsing large domain-literal components, this can cause excessive CPU consumption.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('799e8adf-9e62-4180-b3e0-38041b87afc7', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-61726', 'HIGH', 'stdlib', 'go1.24.3', '1.24.12', '', 'The net/url package does not set a limit on the number of query parameters in a query. While the maximum size of query parameters in URLs is generally limited by the maximum request header size, the net/http.Request.ParseForm method can parse large URL-encoded forms. Parsing a large form containing many unique query parameters can cause excessive memory consumption.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('2fd7ec29-7896-4e16-a1eb-5d5008d5343b', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-61729', 'HIGH', 'stdlib', 'go1.24.3', '1.24.11', '', 'Within HostnameError.Error(), when constructing an error string, there is no limit to the number of hosts that will be printed out. Furthermore, the error string is constructed by repeated string concatenation, leading to quadratic runtime. Therefore, a certificate provided by a malicious actor can result in excessive resource consumption.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('6ebca84d-7a94-49da-8c69-5ea288a88286', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-61731', 'HIGH', 'stdlib', 'go1.24.3', '1.24.12', '', 'Building a malicious file with cmd/go can cause can cause a write to an attacker-controlled file with partial control of the file content. The "#cgo pkg-config:" directive in a Go source file provides command-line arguments to provide to the Go pkg-config command. An attacker can provide a "--log-file" argument to this directive, causing pkg-config to write to an attacker-controlled location.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('a5eca19c-881a-4f74-a670-98469357c324', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-61732', 'HIGH', 'stdlib', 'go1.24.3', '1.24.13', '', 'A discrepancy between how Go and C/C++ comments were parsed allowed for code smuggling into the resulting cgo binary.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('1cee4ed1-c85c-4ea2-a886-83f03f398cdc', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2026-25679', 'HIGH', 'stdlib', 'go1.24.3', '1.25.8', '', 'url.Parse insufficiently validated the host/authority component and accepted some invalid URLs.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('711852da-24ac-4a91-ac99-da6d91aaeac2', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2026-27140', 'HIGH', 'stdlib', 'go1.24.3', '1.25.9', '', 'SWIG file names containing ''cgo'' and well-crafted payloads could lead to code smuggling and arbitrary code execution at build time due to trust layer bypass.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('e52474bc-06c5-4a44-bed8-d879519838a8', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2026-32280', 'HIGH', 'stdlib', 'go1.24.3', '1.25.9', '', 'During chain building, the amount of work that is done is not correctly limited when a large number of intermediate certificates are passed in VerifyOptions.Intermediates, which can lead to a denial of service. This affects both direct users of crypto/x509 and users of crypto/tls.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('53136ec1-5295-41e4-8358-89ac422907e1', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2026-32281', 'HIGH', 'stdlib', 'go1.24.3', '1.25.9', '', 'Validating certificate chains which use policies is unexpectedly inefficient when certificates in the chain contain a very large number of policy mappings, possibly causing denial of service. This only affects validation of otherwise trusted certificate chains, issued by a root CA in the VerifyOptions.Roots CertPool, or in the system certificate pool.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('7f77336c-2f72-4488-a457-9bf02e136f97', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2026-32283', 'HIGH', 'stdlib', 'go1.24.3', '1.25.9', '', 'If one side of the TLS connection sends multiple key update messages post-handshake in a single record, the connection can deadlock, causing uncontrolled consumption of resources. This can lead to a denial of service. This only affects TLS 1.3.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('18742463-88bb-4ca1-a3d6-e23e3c12ef09', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-4673', 'MEDIUM', 'stdlib', 'go1.24.3', '1.23.10', '', 'Proxy-Authorization and Proxy-Authenticate headers persisted on cross-origin redirects potentially leaking sensitive information.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('68d3a174-e882-49a1-ba44-021d0e554389', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-47906', 'MEDIUM', 'stdlib', 'go1.24.3', '1.23.12', '', 'If the PATH environment variable contains paths which are executables (rather than just directories), passing certain strings to LookPath ("", ".", and ".."), can result in the binaries listed in the PATH being unexpectedly returned.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('d7932592-f16c-455d-9eff-c8e9c9217451', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-47912', 'MEDIUM', 'stdlib', 'go1.24.3', '1.24.8', '', 'The Parse function permits values other than IPv6 addresses to be included in square brackets within the host component of a URL. RFC 3986 permits IPv6 addresses to be included within the host component, enclosed within square brackets. For example: "http://[::1]/". IPv4 addresses and hostnames must not appear within square brackets. Parse did not enforce this requirement.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('ff6064fa-bafc-4e20-838a-7f302a8fb788', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-58183', 'MEDIUM', 'stdlib', 'go1.24.3', '1.24.8', '', 'tar.Reader does not set a maximum size on the number of sparse region data blocks in GNU tar pax 1.0 sparse files. A maliciously-crafted archive containing a large number of sparse regions can cause a Reader to read an unbounded amount of data from the archive into memory. When reading from a compressed source, a small compressed input can result in large allocations.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('eb0478a3-c325-4560-9b52-9ab385b09a88', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-58185', 'MEDIUM', 'stdlib', 'go1.24.3', '1.24.8', '', 'Parsing a maliciously crafted DER payload could allocate large amounts of memory, causing memory exhaustion.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('22f8dfc9-ce47-4ba3-96e4-8cbba0cdb34a', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-58186', 'MEDIUM', 'stdlib', 'go1.24.3', '1.24.8', '', 'Despite HTTP headers having a default limit of 1MB, the number of cookies that can be parsed does not have a limit. By sending a lot of very small cookies such as "a=;", an attacker can make an HTTP server allocate a large amount of structs, causing large memory consumption.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('6e3e6edc-a37a-47e0-8eaa-3635e59e04c9', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-58189', 'MEDIUM', 'stdlib', 'go1.24.3', '1.24.8', '', 'When Conn.Handshake fails during ALPN negotiation the error contains attacker controlled information (the ALPN protocols sent by the client) which is not escaped.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('6ce55387-9496-459c-b4d6-c81a52f88de3', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-61724', 'MEDIUM', 'stdlib', 'go1.24.3', '1.24.8', '', 'The Reader.ReadResponse function constructs a response string through repeated string concatenation of lines. When the number of lines in a response is large, this can cause excessive CPU consumption.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('13c0bd13-2626-4f64-8796-465405ec5dd4', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-61727', 'MEDIUM', 'stdlib', 'go1.24.3', '1.24.11', '', 'An excluded subdomain constraint in a certificate chain does not restrict the usage of wildcard SANs in the leaf certificate. For example a constraint that excludes the subdomain test.example.com does not prevent a leaf certificate from claiming the SAN *.example.com.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('57ea28b7-e733-4605-95d4-88ea2c98383a', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-61728', 'MEDIUM', 'stdlib', 'go1.24.3', '1.24.12', '', 'archive/zip uses a super-linear file name indexing algorithm that is invoked the first time a file in an archive is opened. This can lead to a denial of service when consuming a maliciously constructed ZIP archive.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('757c7341-92f3-4d80-8b58-95ffb789c2c0', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2025-61730', 'MEDIUM', 'stdlib', 'go1.24.3', '1.24.12', '', 'During the TLS 1.3 handshake if multiple messages are sent in records that span encryption level boundaries (for instance the Client Hello and Encrypted Extensions messages), the subsequent messages may be processed before the encryption level changes. This can cause some minor information disclosure if a network-local attacker can inject messages during the handshake.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('8cf64840-ffd6-4375-957a-36d729511152', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2026-27142', 'MEDIUM', 'stdlib', 'go1.24.3', '1.25.8', '', 'Actions which insert URLs into the content attribute of HTML meta tags are not escaped. This can allow XSS if the meta tag also has an http-equiv attribute with the value "refresh". A new GODEBUG setting has been added, htmlmetacontenturlescape, which can be used to disable escaping URLs in actions in the meta content attribute which follow "url=" by setting htmlmetacontenturlescape=0.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('201e15b1-c4c6-4fba-8324-73e81df236a5', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2026-32282', 'MEDIUM', 'stdlib', 'go1.24.3', '1.25.9', '', 'On Linux, if the target of Root.Chmod is replaced with a symlink while the chmod operation is in progress, Chmod can operate on the target of the symlink, even when the target lies outside the root. The Linux fchmodat syscall silently ignores the AT_SYMLINK_NOFOLLOW flag, which Root.Chmod uses to avoid symlink traversal. Root.Chmod checks its target before acting and returns an error if the target is a symlink lying outside the root, so the impact is limited to cases where the target is replaced with a symlink between the check and operation.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('8b41e196-b837-49de-b613-55ece4a9396d', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2026-32288', 'MEDIUM', 'stdlib', 'go1.24.3', '1.25.9', '', 'tar.Reader can allocate an unbounded amount of memory when reading a maliciously-crafted archive containing a large number of sparse regions encoded in the "old GNU sparse map" format.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('466bc5ab-1cbe-4f90-99a1-fb633d447ca6', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2026-32289', 'MEDIUM', 'stdlib', 'go1.24.3', '1.25.9', '', 'Context was not properly tracked across template branches for JS template literals, leading to possibly incorrect escaping of content when branches were used. Additionally template actions within JS template literals did not properly track the brace depth, leading to incorrect escaping being applied. These issues could cause actions within JS template literals to be incorrectly or improperly escaped, leading to XSS vulnerabilities.', '/controller', '2026-04-17 15:46:41.495215+00');
INSERT INTO image_vuln_findings (id, image_digest_id, scan_run_id, scanner, vuln_id, severity, pkg_name, installed_version, fixed_version, title, description, target, created_at) VALUES ('14b5f57b-0b36-45ff-8bae-41e2ed709685', '478c676b-c286-485d-8d38-764f1f6ad808', 'fa9b65fa-033f-4666-bd83-1e75d3827716', 'grype', 'CVE-2026-27139', 'LOW', 'stdlib', 'go1.24.3', '1.25.8', '', 'On Unix platforms, when listing the contents of a directory using File.ReadDir or File.Readdir the returned FileInfo could reference a file outside of the Root in which the File was opened. The impact of this escape is limited to reading metadata provided by lstat from arbitrary locations on the filesystem without permitting reading or writing files outside the root.', '/controller', '2026-04-17 15:46:41.495215+00');

COMMIT;
